  ('RAC', 'high_school', '{"title":"ช่างฝีมือผู้พิถีพิถัน","summary":"คุณชอบสร้างงานด้วยมือ ใส่ความสวยงามลงไป และทำทุกขั้นอย่างเป็นระเบียบ ผลงานของคุณจึงทั้งมีสไตล์และเรียบร้อยไร้ที่ติ เหมาะกับงานฝีมือที่ต้องการทั้งศิลปะและความแม่นยำ","strengths":[{"title":"พิถีพิถันทุกรายละเอียด","detail":"เก็บงานเรียบร้อยจนคนอื่นสังเกตได้"},{"title":"มีระบบในการทำงาน","detail":"จัดวัสดุและขั้นตอนให้งานเดินลื่น"},{"title":"สายตาด้านความงาม","detail":"รู้ว่าสัดส่วนหรือสีแบบไหนลงตัว"},{"title":"ทำงานซ้ำได้คุณภาพเดิม","detail":"รักษามาตรฐานของงานได้ทุกชิ้น"}],"careers":[{"title":"ช่างเขียนแบบสถาปัตยกรรม","reason":"แปลงไอเดียของสถาปนิกเป็นแบบที่ถูกต้องครบถ้วน","tag":"จัดระบบ • สร้างสรรค์"},{"title":"นักออกแบบกราฟิกงานพิมพ์","reason":"จัดวางตัวอักษรและภาพให้สวยและพร้อมพิมพ์","tag":"สร้างสรรค์ • จัดระบบ"},{"title":"ช่างทำเครื่องประดับ","reason":"ประดิษฐ์ชิ้นงานละเอียดด้วยมือตามแบบอย่างแม่นยำ","tag":"ลงมือทำ • จัดระบบ"},{"title":"ช่างตัดเย็บและแพตเทิร์น","reason":"วัดและตัดผ้าให้พอดีตัว ได้ทั้งฝีมือและความสวย","tag":"ลงมือทำ • สร้างสรรค์"},{"title":"นักบูรณะงานศิลป์และโบราณวัตถุ","reason":"ซ่อมแซมชิ้นงานเก่าตามขั้นตอนอย่างระมัดระวัง","tag":"ลงมือทำ • จัดระบบ"},{"title":"ผู้ควบคุมการผลิตงานพิมพ์","reason":"คุมสีและคุณภาพงานพิมพ์ให้ตรงกับแบบ","tag":"จัดระบบ • ลงมือทำ"}],"guidance":[{"title":"สถาปัตยกรรมศาสตร์","tag":"สถาปัตยกรรมศาสตร์","detail":"ฝึกเขียนแบบและทำโมเดลอย่างละเอียด ผสมศิลปะกับความแม่นยำ","programs":[{"university":"จุฬาลงกรณ์มหาวิทยาลัย","campus":"วิทยาเขตหลัก","faculty":"คณะสถาปัตยกรรมศาสตร์","program":"หลักสูตรสถาปัตยกรรมศาสตรบัณฑิต สาขาวิชาสถาปัตยกรรม","url":"https://course.mytcas.com/programs/10010125400501A","fieldUrl":"https://course.mytcas.com/universities/001/faculties/25/fields/05","rounds":["รอบ 1","รอบ 2","รอบ 3"]},{"university":"มหาวิทยาลัยศิลปากร","campus":"วังท่าพระ","faculty":"คณะสถาปัตยกรรมศาสตร์","program":"หลักสูตรสถาปัตยกรรมศาสตรบัณฑิต","url":"https://course.mytcas.com/programs/10080102400501A","fieldUrl":"https://course.mytcas.com/universities/008/faculties/