03901301A","fieldUrl":"https://course.mytcas.com/universities/008/faculties/03/fields/13","rounds":["รอบ 1","รอบ 3"]},{"university":"มหาวิทยาลัยธรรมศาสตร์","campus":"ท่าพระจันทร์","faculty":"วิทยาลัยนวัตกรรม","program":"ศศ.บ.สาขาวิชาการจัดการมรดกวัฒนธรรมและอุตสาหกรรมสร้างสรรค์ (โครงการพิเศษ) (ศึกษาที่ มธ.ท่าพระจันทร์)","url":"https://course.mytcas.com/programs/10050123904001B","fieldUrl":"https://course.mytcas.com/universities/005/faculties/23/fields/40","rounds":["รอบ 1","รอบ 2"]}]}],"try_this_week":["ลองวาดแปลนห้องนอนของคุณตามมาตราส่วน","จัดโต๊ะหรือกล่องอุปกรณ์ให้เป็นระเบียบและสวยงาม","ถามรุ่นพี่สถาปัตย์ว่างานเขียนแบบปีหนึ่งเป็นอย่างไร"]}'::jsonb, 'claude-code', true, now()),
